use cranelift::prelude::*;
use cranelift_jit::{JITBuilder, JITModule};
use cranelift_module::{Linkage, Module};
use std::mem;

/// Define the structure of our simple JIT Compiler.
pub struct AgentJitCompiler {
    module: JITModule,
    ctx: codegen::Context,
    builder_context: FunctionBuilderContext,
}

impl AgentJitCompiler {
    /// Initialize a new JIT Compiler instance with a native target.
    pub fn new() -> Self {
        let mut flag_builder = settings::builder();
        // Enable speed optimization flags
        flag_builder.set("opt_level", "speed").unwrap();
        // Enable CPU-specific instruction set extensions (e.g., AVX2, BMI2)
        flag_builder.set("use_colocated_libcalls", "false").unwrap();

        let isa_builder = cranelift_native::builder().unwrap_or_else(|msg| {
            panic!("Host machine ISA detection failed: {}", msg);
        });
        let isa = isa_builder.finish(settings::Flags::new(flag_builder)).unwrap();

        let builder = JITBuilder::with_isa(isa, cranelift_module::default_libcall_names());
        let module = JITModule::new(builder);
        let ctx = module.make_context();
        let builder_context = FunctionBuilderContext::new();

        Self {
            module,
            ctx,
            builder_context,
        }
    }

    /// Compiles an agent routing node.
    /// This function generates machine code that reads an integer score from the execution frame,
    /// compares it to a threshold, and writes the resulting destination node ID back to the frame.
    pub fn compile_router(&mut self, threshold: i64) -> *const u8 {
        let mut sig = self.module.make_signature();
        // The function accepts a single parameter: a pointer to the Agent Execution Frame (RDI / pointer type)
        sig.params.push(AbiParam::new(self.module.target_config().pointer_type()));

        self.ctx.func.signature = sig;

        let mut builder = FunctionBuilder::new(&mut self.ctx.func, &mut self.builder_context);

        // Create the entry block
        let entry_block = builder.create_block();
        builder.append_block_params_for_function_params(entry_block);
        builder.switch_to_block(entry_block);
        builder.seal_block(entry_block);

        // Get the frame pointer argument (RDI)
        let frame_ptr = builder.block_params(entry_block)[0];

        // Load the score from the execution frame (offset 0x10, 8 bytes)
        let score_val = builder.ins().load(
            types::I64,
            MemFlags::trusted(),
            frame_ptr,
            0x10,
        );

        // Define destination blocks
        let pass_block = builder.create_block();
        let fail_block = builder.create_block();
        let merge_block = builder.create_block();

        // Compare score >= threshold
        let threshold_val = builder.ins().iconst(types::I64, threshold);
        builder.ins().br_icmp(
            IntCC::SignedGreaterThanOrEqual,
            score_val,
            threshold_val,
            pass_block,
            &[],
        );

        // If comparison fails, fall through to fail_block
        builder.ins().jump(fail_block, &[]);

        // Pass Block: Set route target to 1 (Node A)
        builder.switch_to_block(pass_block);
        builder.seal_block(pass_block);
        let target_a = builder.ins().iconst(types::I32, 1);
        // Store target ID at offset 0x20 in the frame
        builder.ins().store(MemFlags::trusted(), target_a, frame_ptr, 0x20);
        builder.ins().jump(merge_block, &[]);

        // Fail Block: Set route target to 2 (Node B)
        builder.switch_to_block(fail_block);
        builder.seal_block(fail_block);
        let target_b = builder.ins().iconst(types::I32, 2);
        // Store target ID at offset 0x20 in the frame
        builder.ins().store(MemFlags::trusted(), target_b, frame_ptr, 0x20);
        builder.ins().jump(merge_block, &[]);

        // Merge Block
        builder.switch_to_block(merge_block);
        builder.seal_block(merge_block);
        builder.ins().return_(&[]);

        // Finalize Cranelift compilation
        builder.finalize();

        let func_id = self.module
            .declare_function("agent_route", Linkage::Export, &self.ctx.func.signature)
            .unwrap();

        self.module.define_function(func_id, &mut self.ctx).unwrap();
        self.module.clear_context(&mut self.ctx);

        // Finalize all definitions and make memory executable
        self.module.finalize_definitions().unwrap();

        let code_ptr = self.module.get_finalized_function(func_id);
        code_ptr
    }
}
